from content import *
from html import escape
from pathlib import Path
import json,copy,re
ROOT=Path(__file__).resolve().parent.parent
DATA=json.loads((ROOT/'assets/recipes.json').read_text());REF=json.loads((ROOT/'assets/references.json').read_text());XP=json.loads((ROOT/'assets/xp-table.json').read_text())['totals']
def page(s):return next(x for x in PAGES if x['slug']==s)
def append(s,h,b):page(s)['sections'].append((h,b))
def rt(t):return table([escape(v) for v in t['headers']],[[escape(v) for v in r] for r in t['rows']],True)
def rec(name):return next(r for r in DATA['recipes'] if r['name']==name)
def recipe_rows(rs):
 return [[link('recipe-finder?recipe='+r['id'],escape(r['name'])) if False else '<a href="recipe-finder.html?recipe='+r['id']+'">'+escape(r['name'])+'</a>',str(r['output']),', '.join(str(i['quantity'])+' '+escape(i['name']) for i in r['ingredients']),('Not recorded' if r['xp'] is None else f'{r["xp"]:g}')+' '+r['skill']] for r in rs]
def recipes(names):return table(['Item / open planner','Output','Ingredients per batch','Base XP per batch'],recipe_rows([rec(n) for n in names]),True)
def controls():
 return '''<label class="platform-select">Your controls <select data-platform-select><option value="pc">PC · keyboard & mouse</option><option value="xbox">Xbox Series X|S</option><option value="ps5">PlayStation 5</option><option value="switch">Nintendo Switch 2</option></select></label>'''
def prompt(action):return '<kbd data-action="'+action+'">'+{'inventory':'Tab','interact':'E','map':'M / J','build':'B','quick':'1–8','pause':'Esc'}[action]+'</kbd>'

