   heads=t['headers']
   if 'XP' in heads:
    rows=[]
    for r in t['rows']:
     ix=heads.index('XP'); val=r[ix]; rows.append(r[:ix+1]+[f'{float(val)*3:g}' if re.fullmatch(r'\d+(\.\d+)?',val) else 'Not recorded']+r[ix+1:])
    secs.append(('XP per catch and bait',table(heads[:ix+1]+['At ×3 XP (calculated)']+heads[ix+1:],rows,True)))
